const t = $('When Executed by Another Workflow').first().json;
const row = $input.first().json || {};
let prof = row.profile;
if (typeof prof === 'string') { try { prof = JSON.parse(prof); } catch (e) { prof = {}; } }
prof = prof || {};
const kind = String(t.kind || '').trim();
const num = v => { const n = Number(v); return isFinite(n) ? n : null; };
const r1 = x => Math.round(x * 10) / 10;
if (kind === 'one_rep_max') {
  const w = num(t.weight), r = num(t.reps);
  if (!w || !r || r < 1) return [{ json: { response: 'Для расчёта 1ПМ нужны рабочий вес (weight) и число повторов (reps).' } }];
  const orm = r1(w * (1 + r / 30));
  const pcts = [95, 90, 85, 80, 75, 70, 65, 60];
  const table = pcts.map(p => p + '%=' + r1(orm * p / 100) + 'кг').join(', ');
  const tp = num(t.target_pct);
  const extra = tp ? (' Для ' + tp + '%: ' + r1(orm * tp / 100) + ' кг.') : '';
  return [{ json: { response: 'Расчётный 1ПМ (Epley) ≈ ' + orm + ' кг (из ' + w + 'кг × ' + r + '). Веса по %: ' + table + '.' + extra + ' Это оценка, сверяй с самочувствием и техникой.' } }];
}
if (kind === 'calories') {
  if (!prof || !prof.sex || !prof.height_cm || !prof.current_weight_kg || !prof.birth_date) return [{ json: { response: 'Не хватает данных профиля для расчёта калорий (нужны пол, рост, вес, дата рождения). Собери их и попробуй снова.' } }];
  const maxAge = num(row.weight_max_age) || 7;
  if (prof.current_weight_on) { const days = Math.floor((Date.now() - Date.parse(prof.current_weight_on)) / 86400000); if (days > maxAge) return [{ json: { response: 'Вес устарел: последний замер ' + days + ' дн назад (порог свежести ' + maxAge + ' дн). Попроси клиента взвеситься, затем посчитаю — по протухшему весу считать нельзя.' } }]; }
  const w = num(prof.current_weight_kg), h = num(prof.height_cm);
  const age = Math.floor((Date.now() - Date.parse(prof.birth_date)) / (365.25 * 86400000));
  const s = prof.sex === 'male' ? 5 : (prof.sex === 'female' ? -161 : -78);
  const bmr = 10 * w + 6.25 * h - 5 * age + s;
  const days = num(prof.days_per_week);
  const af = days >= 6 ? 1.725 : (days >= 3 ? 1.55 : (days >= 1 ? 1.375 : 1.2));
  const tdee = Math.round(bmr * af);
  let dir = String(t.goal_direction || '').trim().toLowerCase();
  if (!['cut', 'bulk', 'maintain'].includes(dir)) { const g = String(prof.main_goal || '').toLowerCase(); dir = /похуд|жир|сушк|рельеф|скинуть|снизить/.test(g) ? 'cut' : (/масс|набор|силу|силов/.test(g) ? 'bulk' : 'maintain'); }
  const target = dir === 'cut' ? Math.round(tdee * 0.8) : (dir === 'bulk' ? Math.round(tdee * 1.1) : tdee);
  const protein = Math.round(2.0 * w), fat = Math.round(0.9 * w);
  const carb = Math.max(0, Math.round((target - (protein * 4 + fat * 9)) / 4));
  const dirRu = dir === 'cut' ? 'дефицит ~20%' : (dir === 'bulk' ? 'профицит ~10%' : 'поддержание');
  return [{ json: { response: 'Расчёт кодом (Mifflin-St Jeor): пол ' + prof.sex + ', возраст ' + age + ', вес ' + w + 'кг, рост ' + h + 'см, активность ×' + af + '. BMR ' + Math.round(bmr) + ', TDEE ' + tdee + ' ккал. Цель — ' + dirRu + ': ЦЕЛЕВЫЕ ' + target + ' ккал/день. БЖУ: белок ' + protein + 'г, жиры ' + fat + 'г, углеводы ' + carb + 'г. Стартовая оценка — корректируй по динамике веса за 2-3 недели.' } }];
}
return [{ json: { response: 'Неизвестный тип расчёта. Доступно: calories, one_rep_max.' } }];
